using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class LabDoorAudit{
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/검수/2026-11-07_C01_Doors/";
 public static object Restore(){if(Application.isPlaying)throw new Exception("Stop play first");var s=SceneManager.GetActiveScene();if(!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Unexpected scene");EditorSceneManager.OpenScene(s.path);return Run();}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(d=>Vector3.Distance(d.position,room.position)<12).ToArray();var results=new List<object>();
 try{foreach(var d in doors){var p=d.Find("Clinical_Portal");var frame=p.GetComponentsInChildren<MeshCollider>().Single();var leaves=new[]{p.Find("Leaf_Left"),p.Find("Leaf_Right")};int openBlocked=0;Physics.SyncTransforms();for(int j=0;j<=26;j++)foreach(float x in new[]{-.85f,0,.85f}){var at=p.TransformPoint(new Vector3(x,0,-1.3f+j*.1f));if(Physics.OverlapCapsule(at+Vector3.up*.34f,at+Vector3.up*1.5f,.28f,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform.IsChildOf(d)&&!c.name.Contains("Threshold")))openBlocked++;}
 var penetrations=new List<object>();int poses=0;foreach(var leaf in leaves){var c=leaf.GetComponent<BoxCollider>();float side=leaf.name.Contains("Left")?-1:1;for(int i=0;i<=20;i++){leaf.localPosition=new Vector3(side*1.235f*i/20,0,0);Physics.SyncTransforms();Vector3 direction;float depth;if(Physics.ComputePenetration(c,c.transform.position,c.transform.rotation,frame,frame.transform.position,frame.transform.rotation,out direction,out depth)&&depth>.001f)penetrations.Add(new{leaf=leaf.name,i,depth});poses++;}leaf.localPosition=Vector3.zero;}
 Physics.SyncTransforms();int samples=0,missing=0,upperSamples=0,upperMissing=0;var failures=new List<object>();for(float x=-2.04f;x<2.05f;x+=.06f){float top=1.3f+Mathf.Sqrt(2.1f*2.1f-x*x);for(float y=.055f;y<top-.018f;y+=.055f){samples++;bool hit=Physics.RaycastAll(p.TransformPoint(new Vector3(x,y,-1.4f)),p.forward,3f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.collider.transform.IsChildOf(p));if(y>3.08f)upperSamples++;if(!hit){missing++;if(y>3.08f)upperMissing++;if(failures.Count<15)failures.Add(new{x,y});}}}
 bool closedBlocks=Physics.OverlapCapsule(p.position+Vector3.up*.34f,p.position+Vector3.up*1.5f,.28f,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform.IsChildOf(p));foreach(var leaf in leaves)leaf.localPosition=p.Find(leaf.name.Contains("Left")?"Left_Open":"Right_Open").localPosition;Physics.SyncTransforms();
 // Old door crown coverage, using its preserved original pose.
 var old=d.Find("Previous_Rectangular_Door_Inactive");p.gameObject.SetActive(false);old.gameObject.SetActive(true);Physics.SyncTransforms();int oldUpperMissing=0;for(float x=-2.04f;x<2.05f;x+=.06f){float top=1.3f+Mathf.Sqrt(2.1f*2.1f-x*x);for(float y=3.135f;y<top-.018f;y+=.055f)if(!Physics.RaycastAll(p.TransformPoint(new Vector3(x,y,-1.4f)),p.forward,3f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.collider.transform.IsChildOf(old)))oldUpperMissing++;}old.gameObject.SetActive(false);p.gameObject.SetActive(true);Physics.SyncTransforms();results.Add(new{d.name,openSamples=81,openBlocked,closedBlocks,closedCoverageSamples=samples,closedCoverageMissing=missing,upperSamples,upperMissing,oldUpperMissing,slidePoses=poses,penetrations,failures});}
 var before=JObject.Parse(File.ReadAllText(O+"before.json"));var stations=JArray.FromObject(room.Find("C01_Perimeter_Lab").Cast<Transform>().Select(t=>new{t.name,p=t.localPosition.ToString("F6"),r=t.localEulerAngles.ToString("F6"),s=t.localScale.ToString("F6")}));var player=JArray.FromObject(s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).Select(g=>new{g.name,p=g.transform.position.ToString("F6"),r=g.transform.eulerAngles.ToString("F6")}));var meshes=AssetDatabase.LoadAllAssetsAtPath("Assets/Afrer_Seconds/05.Model/Environment/B5/CDR_ClinicalPortal.fbx").OfType<Mesh>().ToArray();int bad=0,triangles=0;foreach(var m in meshes){var v=m.vertices;var tr=m.triangles;triangles+=tr.Length/3;for(int i=0;i<tr.Length;i+=3)if(Vector3.Cross(v[tr[i+1]]-v[tr[i]],v[tr[i+2]]-v[tr[i]]).magnitude*.5f<5e-9f)bad++;}int missingMaterials=doors.SelectMany(d=>d.Find("Clinical_Portal").GetComponentsInChildren<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name=="Hidden/InternalErrorShader"));var result=new{doors=results,stationsPreserved=JToken.DeepEquals(before["stations"],stations),playerPreserved=JToken.DeepEquals(before["player"],player),modelMeshes=meshes.Length,triangles,degenerateTriangles=bad,missingMaterials};File.WriteAllText(O+"door_audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }finally{EditorSceneManager.OpenScene(s.path);}}
}
